insert into app.business_rule_catalog(rule_key,domain,title,description,source,precedence,enforcement,status,test_status,source_ref,metadata)
values
('SPORT-001','sports','One stat row per Tanner and match','A linked Tanner has at most one canonical performance row per match; repeated capture updates the same row.','legacy',90,'database','active','tested','TannerOS v1 matchStats + app_match_stats_org_match_player_uidx','{"qa":"same player/match returned same stat id; rollback clean"}'::jsonb),
('SPORT-002','sports','Match performance is internally consistent','Performance counters cannot be negative and a Tanner marked as not attended cannot have starter/minutes/goals/cards/saves/clean-sheet performance.','approved_v2',100,'command','active','tested','private.command_upsert_match_stat','{"qa":"unattended performance rejected; rollback clean"}'::jsonb),
('EVAL-001','sports','Player evaluations use canonical 0-10 scores','Technical, intelligence, intensity, mentality, values and goalkeeper dimensions are validated 0-10 and evaluator identity is derived from authenticated context.','legacy',90,'command','active','tested','TannerOS v1 evaluations / private.command_upsert_player_evaluation','{"qa":"score 11 rejected; authenticated evaluator; rollback clean"}'::jsonb),
('NOTE-001','sports','Player notes preserve authenticated authorship','Player notes are written through an authorized Players command and preserve date, context, text and authenticated author label.','legacy',90,'command','active','tested','TannerOS v1 playerNotes / private.command_upsert_player_note','{"qa":"note visible in sports profile; rollback clean"}'::jsonb),
('SPORT-003','sports','Sports profile derives from canonical history','Player performance KPIs and recent history derive from canonical matches, match stats, evaluations and notes rather than duplicated browser calculations.','legacy',90,'workflow','active','tested','TannerOS v1 playerMatchStats / private.query_player_sports','{"qa":"match+evaluation+note reconciled in one profile"}'::jsonb)
